    wire [5:0] pc3_w1_2 = {3'b0, pc3_a4} + {3'b0, pc3_a5};
    wire [5:0] pc3_w1_3 = {3'b0, pc3_a6};
    reg [5:0] pc3_r2_0 = 0;
    reg [5:0] pc3_r2_1 = 0;
    always @(posedge clk) begin
        pc3_r2_0 <= pc3_w1_0 + pc3_w1_1;
        pc3_r2_1 <= pc3_w1_2 + pc3_w1_3;
    end
    reg [5:0] pc3_r3_0 = 0;
    always @(posedge clk) begin
        pc3_r3_0 <= pc3_r2_0 + pc3_r2_1;
    end
    wire [5:0] pc4_w1_0 = {3'b0, pc4_a0} + {3'b0, pc4_a1};
    wire [5:0] pc4_w1_1 = {3'b0, pc4_a2} + {3'b0, pc4_a3};
    wire [5:0] pc4_w1_2 = {3'b0, pc4_a4} + {3'b0, pc4_a5};
    wire [5:0] pc4_w1_3 = {3'b0, pc4_a6};
    reg [5:0] pc4_r2_0 = 0;
    reg [5:0] pc4_r2_1 = 0;
    always @(posedge clk) begin
        pc4_r2_0 <= pc4_w1_0 + pc4_w1_1;
        pc4_r2_1 <= pc4_w1_2 + pc4_w1_3;
    end
    reg [5:0] pc4_r3_0 = 0;
    always @(posedge clk) begin
        pc4_r3_0 <= pc4_r2_0 + pc4_r2_1;
    end
    wire [5:0] am_v [0:4];
    assign am_v[0] = pc0_r3_0;
    assign am_v[1] = pc1_r3_0;
    assign am_v[2] = pc2_r3_0;
    assign am_v[3] = pc3_r3_0;
    assign am_v[4] = pc4_r3_0;
    reg [5:0] am_best;
