    integer ai;
    always @(posedge clk) begin
        am_best = am_v[0]; am_idx = 3'd0;
        for (ai = 1; ai < 5; ai = ai + 1)
            if (am_v[ai] > am_best) begin am_best = am_v[ai]; am_idx = ai; end
        y <= am_idx;
    end
endmodule
